func formalCasesPath(t *testing.T) string {
	t.Helper()
	if path := os.Getenv("C1Z_FORMAL_CASES"); path != "" {
		return path
	}
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("runtime.Caller failed; cannot locate formal/c1z/generated/cases.json")
	}
	return filepath.Join(filepath.Dir(file), "..", "..", "..", "..", "formal", "c1z", "generated", "cases.json")
}

// formalFamilyLens returns the length of each family's array, keyed by
// the family's JSON name.
func formalFamilyLens(cases *formalCases) map[string]int {
	return map[string]int{
		"keys":                len(cases.Keys),
		"entitlement_strip":   len(cases.EntitlementStrip),
		"writes":              len(cases.Writes),
		"pagination":          len(cases.Pagination),
		"bare_id":             len(cases.BareID),
		"sync":                len(cases.Sync),
		"grant_writes":        len(cases.GrantWrites),
		"entitlement_writes":  len(cases.EntitlementWrites),
		"grant_list":          len(cases.GrantList),
		"grants_by_principal": len(cases.GrantsByPrincipal),
		"grant_bare_id":       len(cases.GrantBareID),
		"stream":              len(cases.Stream),
		"digest":              len(cases.Digest),
		"reopen":              len(cases.Reopen),
		"views":               len(cases.Views),
		"container":           len(cases.Container),
	}
}

// decodeFormalCases strictly decodes one oracle document and checks
// version and counts. It does not require any family to be non-empty.
func decodeFormalCases(r io.Reader) (*formalCases, error) {
	dec := json.NewDecoder(r)
	dec.DisallowUnknownFields()
	var cases formalCases
	if err := dec.Decode(&cases); err != nil {
		return nil, fmt.Errorf("decode: %w", err)
	}
	if dec.More() {
		return nil, errors.New("decode: trailing data after the JSON document")
	}
	if cases.Version == nil {
		return nil, fmt.Errorf("oracle version is absent, want %d", formalOracleVersion)
	}
	if *cases.Version != formalOracleVersion {
		return nil, fmt.Errorf("oracle version = %d, want %d", *cases.Version, formalOracleVersion)
	}
	lens := formalFamilyLens(&cases)
	if len(cases.Counts) != len(lens) {
		return nil, fmt.Errorf("counts has %d families %v, want exactly %d", len(cases.Counts), cases.Counts, len(lens))
	}
	for family, n := range lens {
		want, ok := cases.Counts[family]
		if !ok {
			return nil, fmt.Errorf("counts is missing family %q", family)
		}
		if want != n {
			return nil, fmt.Errorf("counts[%q] = %d, but the %q array has %d cases", family, want, family, n)
		}
	}
	return &cases, nil
}

func loadFormalCases(t *testing.T) *formalCases {
	t.Helper()
	path := formalCasesPath(t)
	t.Logf("reading oracle cases from %s", path)
	f, err := os.Open(path)
	if err != nil {
		t.Fatalf("open %s: %v (regenerate with `make formal-c1z-oracle`)", path, err)
	}
	defer f.Close()
	cases, err := decodeFormalCases(f)
	if err != nil {
		t.Fatalf("%s: %v", path, err)
	}
	for family, n := range formalFamilyLens(cases) {
		if n == 0 {
			t.Fatalf("family %q is empty", family)
		}
	}
	return cases
}

func requireHex(t *testing.T, field string, h hexField) string {
	t.Helper()
	if !h.present {
		t.Fatalf("required hex field %q is absent", field)
	}
	return h.b
}

func requireNoHex(t *testing.T, field string, h hexField) {
	t.Helper()
	if h.present {
		t.Fatalf("field %q must be absent for this case", field)
	}
}

// requireProtoString returns s if it is valid UTF-8. proto3 string fields
// reject invalid UTF-8 at marshal time, so such a case cannot reach the
// engine through the v2 API.
func requireProtoString(t *testing.T, field, s string) string {
	t.Helper()
	if !utf8.ValidString(s) {
		t.Fatalf("field %q is not valid UTF-8 (%x); proto3 string fields cannot carry it", field, s)
	}
	return s
}

func requireNamesUnique(t *testing.T, family string, names []string) {
	t.Helper()
	seen := make(map[string]bool, len(names))
	for _, n := range names {
		if n == "" {
			t.Fatalf("%s: case with empty name", family)
		}
		if seen[n] {
			t.Fatalf("%s: duplicate case name %q", family, n)
		}
		seen[n] = true
	}
}

func TestFormalConformance(t *testing.T) {
	replayFormalCases(t, loadFormalCases(t), nil)
}

// formalFailureHook runs in a failed case's cleanup with the case's
// family and its index in that family's array.
type formalFailureHook func(t *testing.T, family string, index int)

// replayFormalCases runs every case of every family as a parallel
// subtest. Cases are independent: each engine-backed case opens its own
// engine in its own temp dir, and onFail reads only the case document.
func replayFormalCases(t *testing.T, cases *formalCases, onFail formalFailureHook) {
	t.Helper()
	run := func(t *testing.T, family, name string, i int, f func(t *testing.T)) {
		t.Helper()
		t.Run(name, func(t *testing.T) {
			t.Parallel()
			if onFail != nil {
				t.Cleanup(func() {
					if t.Failed() {
						onFail(t, family, i)
					}
				})
			}
			f(t)
		})
	}
	t.Run("keys", func(t *testing.T) {
		names := make([]string, 0, len(cases.Keys))
		for _, c := range cases.Keys {
			names = append(names, c.Name)
		}
		requireNamesUnique(t, "keys", names)
		for i, c := range cases.Keys {
			run(t, "keys", c.Name, i, func(t *testing.T) { runFormalKeyCase(t, c) })
		}
	})
	t.Run("entitlement_strip", func(t *testing.T) {
		for i, c := range cases.EntitlementStrip {
			run(t, "entitlement_strip", strconv.Itoa(i), i, func(t *testing.T) { runFormalStripCase(t, c) })
		}
	})
	t.Run("writes", func(t *testing.T) {
		names := make([]string, 0, len(cases.Writes))
		for _, c := range cases.Writes {
			names = append(names, c.Name)
		}
		requireNamesUnique(t, "writes", names)
		for i, c := range cases.Writes {
			run(t, "writes", c.Name, i, func(t *testing.T) { runFormalWritesCase(t, c) })
		}
	})
	t.Run("pagination", func(t *testing.T) {
		names := make([]string, 0, len(cases.Pagination))
		for _, c := range cases.Pagination {
			names = append(names, c.Name)
		}
		requireNamesUnique(t, "pagination", names)
		for i, c := range cases.Pagination {
			run(t, "pagination", c.Name, i, func(t *testing.T) { runFormalPaginationCase(t, c) })
		}
	})
	t.Run("bare_id", func(t *testing.T) {
		names := make([]string, 0, len(cases.BareID))
		for _, c := range cases.BareID {
			names = append(names, c.Name)
		}
		requireNamesUnique(t, "bare_id", names)
		for i, c := range cases.BareID {
			run(t, "bare_id", c.Name, i, func(t *testing.T) { runFormalBareIDCase(t, c) })
		}
	})
	t.Run("sync", func(t *testing.T) {
		names := make([]string, 0, len(cases.Sync))
		for _, c := range cases.Sync {
			names = append(names, c.Name)
		}
		requireNamesUnique(t, "sync", names)
		for i, c := range cases.Sync {
			run(t, "sync", c.Name, i, func(t *testing.T) { runFormalSyncCase(t, c) })
		}
	})
	t.Run("grant_writes", func(t *testing.T) {
		names := make([]string, 0, len(cases.GrantWrites))
		for _, c := range cases.GrantWrites {
			names = append(names, c.Name)
		}
		requireNamesUnique(t, "grant_writes", names)
		for i, c := range cases.GrantWrites {
			run(t, "grant_writes", c.Name, i, func(t *testing.T) { runFormalGrantWritesCase(t, c) })
		}
	})
	t.Run("entitlement_writes", func(t *testing.T) {
		names := make([]string, 0, len(cases.EntitlementWrites))
		for _, c := range cases.EntitlementWrites {
			names = append(names, c.Name)
		}
		requireNamesUnique(t, "entitlement_writes", names)
		for i, c := range cases.EntitlementWrites {
			run(t, "entitlement_writes", c.Name, i, func(t *testing.T) { runFormalEntWritesCase(t, c) })
		}
	})
	t.Run("grant_list", func(t *testing.T) {
		names := make([]string, 0, len(cases.GrantList))
		for _, c := range cases.GrantList {
			names = append(names, c.Name)
		}
		requireNamesUnique(t, "grant_list", names)
		for i, c := range cases.GrantList {
			run(t, "grant_list", c.Name, i, func(t *testing.T) { runFormalGrantListCase(t, c) })
		}
	})
	t.Run("grants_by_principal", func(t *testing.T) {
		names := make([]string, 0, len(cases.GrantsByPrincipal))
		for _, c := range cases.GrantsByPrincipal {
			names = append(names, c.Name)
		}
		requireNamesUnique(t, "grants_by_principal", names)
		for i, c := range cases.GrantsByPrincipal {
			run(t, "grants_by_principal", c.Name, i, func(t *testing.T) { runFormalGrantsByPrincipalCase(t, c) })
		}
	})
	t.Run("grant_bare_id", func(t *testing.T) {
		names := make([]string, 0, len(cases.GrantBareID))
		for _, c := range cases.GrantBareID {
			names = append(names, c.Name)
		}
		requireNamesUnique(t, "grant_bare_id", names)
		for i, c := range cases.GrantBareID {
			run(t, "grant_bare_id", c.Name, i, func(t *testing.T) { runFormalGrantBareIDCase(t, c) })
		}
	})
	t.Run("stream", func(t *testing.T) {
		names := make([]string, 0, len(cases.Stream))
		for _, c := range cases.Stream {
			names = append(names, c.Name)
		}
		requireNamesUnique(t, "stream", names)
		for i, c := range cases.Stream {
			run(t, "stream", c.Name, i, func(t *testing.T) { runFormalStreamCase(t, c) })
		}
	})
	t.Run("digest", func(t *testing.T) {
		names := make([]string, 0, len(cases.Digest))
		for _, c := range cases.Digest {
			names = append(names, c.Name)
		}
		requireNamesUnique(t, "digest", names)
		for i, c := range cases.Digest {
			run(t, "digest", c.Name, i, func(t *testing.T) { runFormalDigestCase(t, c) })
		}
	})
	t.Run("reopen", func(t *testing.T) {
		names := make([]string, 0, len(cases.Reopen))
		for _, c := range cases.Reopen {
			names = append(names, c.Name)
		}
		requireNamesUnique(t, "reopen", names)
		for i, c := range cases.Reopen {
			run(t, "reopen", c.Name, i, func(t *testing.T) { runFormalReopenCase(t, c) })
		}
	})
	t.Run("views", func(t *testing.T) {
		names := make([]string, 0, len(cases.Views))
		for _, c := range cases.Views {
			names = append(names, c.Name)
		}
		requireNamesUnique(t, "views", names)
		for i, c := range cases.Views {
			run(t, "views", c.Name, i, func(t *testing.T) { runFormalViewsCase(t, c) })
		}
	})
}

func runFormalKeyCase(t *testing.T, c formalKeyCase) {
	want := []byte(requireHex(t, "key", c.Key))
	var got []byte
	switch c.Kind {
	case "resource_type":
		requireNoHex(t, "rt", c.RT)
		requireNoHex(t, "rid", c.RID)
		requireNoHex(t, "prt", c.PRT)
		requireNoHex(t, "prid", c.PRID)
		got = encodeResourceTypeKey(requireHex(t, "ext", c.Ext))
	case "resource":
		requireNoHex(t, "ext", c.Ext)
		requireNoHex(t, "prt", c.PRT)
		requireNoHex(t, "prid", c.PRID)
		got = encodeResourceKey(requireHex(t, "rt", c.RT), requireHex(t, "rid", c.RID))
	case "entitlement":
		requireNoHex(t, "prt", c.PRT)
		requireNoHex(t, "prid", c.PRID)
		got = encodeEntitlementIdentityKey(entitlementIdentityFromParts(
			requireHex(t, "rt", c.RT), requireHex(t, "rid", c.RID), requireHex(t, "ext", c.Ext)))
	case "grant":
		got = encodeGrantIdentityKey(grantIdentity{
			entitlement: entitlementIdentityFromParts(
				requireHex(t, "rt", c.RT), requireHex(t, "rid", c.RID), requireHex(t, "ext", c.Ext)),
			principalTypeID: requireHex(t, "prt", c.PRT),
			principalID:     requireHex(t, "prid", c.PRID),
		})
	default:
		t.Fatalf("unknown key kind %q", c.Kind)
	}
	if !bytes.Equal(got, want) {
		t.Fatalf("%s key mismatch:\n got  %x\n want %x", c.Kind, got, want)
	}
}

func runFormalStripCase(t *testing.T, c formalStripCase) {
	if c.Stripped == nil {
		t.Fatal("required field \"stripped\" is absent")
	}
	rt, rid, ext := requireHex(t, "rt", c.RT), requireHex(t, "rid", c.RID), requireHex(t, "ext", c.Ext)
	wantTail := requireHex(t, "tail", c.Tail)
	id := entitlementIdentityFromParts(rt, rid, ext)
	if id.stripped != *c.Stripped || id.tail != wantTail {
		t.Fatalf("entitlementIdentityFromParts(%x, %x, %x) = (stripped=%v, tail=%x), want (stripped=%v, tail=%x)",
			rt, rid, ext, id.stripped, id.tail, *c.Stripped, wantTail)
	}
	if id.resourceTypeID != rt || id.resourceID != rid {
		t.Fatalf("entitlementIdentityFromParts changed owner: got (%x, %x), want (%x, %x)", id.resourceTypeID, id.resourceID, rt, rid)
	}
	if got := id.externalID(); got != ext {
		t.Fatalf("externalID() = %x, want %x", got, ext)
	}
}

// newFormalEngine opens an engine over an in-memory filesystem. The model
// has no filesystem semantics, and the on-disk fsyncs in EndSync serialize
// parallel cases at the device. C1Z_FORMAL_DISK=1 opens on disk instead.
func newFormalEngine(t *testing.T) *Engine {
	t.Helper()
	if os.Getenv("C1Z_FORMAL_DISK") == "1" {
		e, _ := newTestEngine(t)
		return e
	}
	e, _ := newTestEngine(t, WithVFS(vfs.NewMem()))
	return e
}

func newFormalEngineWithSync(t *testing.T) (context.Context, *Engine) {
	t.Helper()
	ctx := context.Background()
	e := newFormalEngine(t)
	if _, err := e.StartNewSync(ctx, connectorstore.SyncTypeFull, ""); err != nil {
		t.Fatalf("StartNewSync: %v", err)
	}
	return ctx, e
}

func formalResource(t *testing.T, rt, rid, displayName string) *v2.Resource {
	t.Helper()
	return v2.Resource_builder{
		Id: v2.ResourceId_builder{
			ResourceType: requireProtoString(t, "rt", rt),
			Resource:     requireProtoString(t, "rid", rid),
		}.Build(),
		DisplayName: requireProtoString(t, "value", displayName),
	}.Build()
}

// listAllFormalResources pages ListResources at MaxPageSize until the
// token is empty.
func listAllFormalResources(ctx context.Context, t *testing.T, e *Engine, rt string) []*v2.Resource {
	t.Helper()
	var out []*v2.Resource
	token := ""
	for {
		resp, err := e.ListResources(ctx, v2.ResourcesServiceListResourcesRequest_builder{
			ResourceTypeId: rt,
			PageSize:       MaxPageSize,
			PageToken:      token,
		}.Build())
		if err != nil {
			t.Fatalf("ListResources: %v", err)
		}
		out = append(out, resp.GetList()...)
		token = resp.GetNextPageToken()
		if token == "" {
			return out
		}
	}
}

func runFormalWritesCase(t *testing.T, c formalWritesCase) {
	rt := requireProtoString(t, "rt", requireHex(t, "rt", c.RT))
	if c.Final == nil {
		t.Fatal("required field \"final\" is absent")
	}
	ctx, e := newFormalEngineWithSync(t)
	for i, op := range c.Ops {
		switch op.Op {
		case "put":
			requireNoHex(t, "rid", op.RID)
			if op.Batch == nil {
				t.Fatalf("op %d: put without \"batch\"", i)
			}
			batch := make([]*v2.Resource, 0, len(*op.Batch))
			for _, r := range *op.Batch {
				if r.Value == nil {
					t.Fatalf("op %d: batch record without \"value\"", i)
				}
				batch = append(batch, formalResource(t, rt, requireHex(t, "rid", r.RID), *r.Value))
			}
			if err := e.PutResources(ctx, batch...); err != nil {
				t.Fatalf("op %d: PutResources: %v", i, err)
			}
		case "delete":
			if op.Batch != nil {
				t.Fatalf("op %d: delete with \"batch\"", i)
			}
			rid := requireProtoString(t, "rid", requireHex(t, "rid", op.RID))
			if err := e.DeleteResourceRecord(ctx, rt, rid); err != nil {
				t.Fatalf("op %d: DeleteResourceRecord: %v", i, err)
			}
		default:
			t.Fatalf("op %d: unknown writes op %q", i, op.Op)
		}
	}
	got := listAllFormalResources(ctx, t, e, rt)
	want := *c.Final
	if len(got) != len(want) {
		t.Fatalf("listed %d resources, want %d: got %v", len(got), len(want), formalResourceSummary(got))
	}
	for i, w := range want {
		if w.Value == nil {
			t.Fatalf("final[%d] without \"value\"", i)
		}
		wantRID := requireHex(t, "rid", w.RID)
		g := got[i]
		if g.GetId().GetResourceType() != rt || g.GetId().GetResource() != wantRID || g.GetDisplayName() != *w.Value {
			t.Fatalf("final[%d] = (rt=%x, rid=%x, value=%q), want (rt=%x, rid=%x, value=%q); full list %v",
				i, g.GetId().GetResourceType(), g.GetId().GetResource(), g.GetDisplayName(), rt, wantRID, *w.Value, formalResourceSummary(got))
		}
	}
}

func formalResourceSummary(rs []*v2.Resource) []string {
	out := make([]string, 0, len(rs))
	for _, r := range rs {
		out = append(out, hex.EncodeToString([]byte(r.GetId().GetResource()))+"="+r.GetDisplayName())
	}
	return out
}

func runFormalPaginationCase(t *testing.T, c formalPaginationCase) {
	rt := requireProtoString(t, "rt", requireHex(t, "rt", c.RT))
	if c.RIDs == nil || c.PageSize == nil || c.Pages == nil {
		t.Fatal("pagination case requires \"rids\", \"page_size\", and \"pages\"")
	}
	ctx, e := newFormalEngineWithSync(t)
	if len(*c.RIDs) > 0 {
		batch := make([]*v2.Resource, 0, len(*c.RIDs))
		for _, h := range *c.RIDs {
			batch = append(batch, formalResource(t, rt, requireHex(t, "rids[]", h), "p"))
		}
		if err := e.PutResources(ctx, batch...); err != nil {
			t.Fatalf("PutResources: %v", err)
		}
	}
	token := ""
	for i, page := range *c.Pages {
		if page.RIDs == nil || page.HasNext == nil {
			t.Fatalf("pages[%d] requires \"rids\" and \"has_next\"", i)
		}
		resp, err := e.ListResources(ctx, v2.ResourcesServiceListResourcesRequest_builder{
			ResourceTypeId: rt,
			PageSize:       *c.PageSize,
			PageToken:      token,
		}.Build())
		if err != nil {
			t.Fatalf("pages[%d]: ListResources: %v", i, err)
		}
		gotRIDs := make([]string, 0, len(resp.GetList()))
		for _, r := range resp.GetList() {
			gotRIDs = append(gotRIDs, hex.EncodeToString([]byte(r.GetId().GetResource())))
		}
		wantRIDs := make([]string, 0, len(*page.RIDs))
		for _, h := range *page.RIDs {
			wantRIDs = append(wantRIDs, hex.EncodeToString([]byte(requireHex(t, "pages[].rids[]", h))))
		}
		if !equalStrings(gotRIDs, wantRIDs) {
			t.Fatalf("pages[%d] rids = %v, want %v", i, gotRIDs, wantRIDs)
		}
		token = resp.GetNextPageToken()
		if gotNext := token != ""; gotNext != *page.HasNext {
			t.Fatalf("pages[%d] has_next = %v, want %v", i, gotNext, *page.HasNext)
		}
		if token == "" && i != len(*c.Pages)-1 {
			t.Fatalf("token ended after page %d, want %d pages", i, len(*c.Pages))
		}
	}
	if token != "" {
		t.Fatalf("token still set after the last expected page %d", len(*c.Pages)-1)
	}
}

func equalStrings(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func runFormalBareIDCase(t *testing.T, c formalBareIDCase) {
	lookup := requireProtoString(t, "lookup", requireHex(t, "lookup", c.Lookup))
	ctx, e := newFormalEngineWithSync(t)
	ents := make([]*v2.Entitlement, 0, len(c.Entitlements))
	for _, ref := range c.Entitlements {
		rt := requireProtoString(t, "rt", requireHex(t, "rt", ref.RT))
		rid := requireProtoString(t, "rid", requireHex(t, "rid", ref.RID))
		ext := requireProtoString(t, "ext", requireHex(t, "ext", ref.Ext))
		ents = append(ents, v2.Entitlement_builder{
			Id: ext,
			Resource: v2.Resource_builder{
				Id: v2.ResourceId_builder{ResourceType: rt, Resource: rid}.Build(),
			}.Build(),
		}.Build())
	}
	if len(ents) > 0 {
		if err := e.PutEntitlements(ctx, ents...); err != nil {
			t.Fatalf("PutEntitlements: %v", err)
		}
	}
	switch c.Expected {
	case "not_found", "ambiguous":
		if c.Found != nil {
			t.Fatalf("expected %q with a \"found\" object", c.Expected)
		}
	case "found":
		if c.Found == nil {
			t.Fatal("expected \"found\" without a \"found\" object")
		}
	default:
		t.Fatalf("unknown bare_id expected %q", c.Expected)
	}
	resp, err := e.GetEntitlement(ctx, reader_v2.EntitlementsReaderServiceGetEntitlementRequest_builder{
		EntitlementId: lookup,
	}.Build())
	var got string
	switch {
	case err == nil:
		got = "found"
	case errors.Is(err, pebble.ErrNotFound):
		got = "not_found"
	case errors.Is(err, ErrAmbiguousExternalID):
		got = "ambiguous"
	default:
		t.Fatalf("GetEntitlement(%x): unexpected error: %v", lookup, err)
	}
	if got != c.Expected {
		t.Fatalf("GetEntitlement(%x) = %s (err=%v), want %s", lookup, got, err, c.Expected)
	}
	if got != "found" {
		return
	}
	wantRT, wantRID, wantExt := requireHex(t, "found.rt", c.Found.RT), requireHex(t, "found.rid", c.Found.RID), requireHex(t, "found.ext", c.Found.Ext)
	ent := resp.GetEntitlement()
	gotRT, gotRID, gotExt := ent.GetResource().GetId().GetResourceType(), ent.GetResource().GetId().GetResource(), ent.GetId()
	if gotRT != wantRT || gotRID != wantRID || gotExt != wantExt {
		t.Fatalf("GetEntitlement(%x) = (rt=%x, rid=%x, ext=%x), want (rt=%x, rid=%x, ext=%x)",
			lookup, gotRT, gotRID, gotExt, wantRT, wantRID, wantExt)
	}
}

func formalSyncType(t *testing.T, s string, allowAny bool) connectorstore.SyncType {
	t.Helper()
	switch s {
	case "full":
		return connectorstore.SyncTypeFull
	case "partial":
		return connectorstore.SyncTypePartial
	case "resources_only":
		return connectorstore.SyncTypeResourcesOnly
	case "any":
		if allowAny {
			return connectorstore.SyncTypeAny
		}
	}
	t.Fatalf("unknown sync type %q", s)
	return ""
}

// formalSyncIDs maps the oracle's symbolic sync ids to KSUIDs, which
// codec.EncodeSyncID requires, and back.
type formalSyncIDs struct {
	toEngine   map[string]string
	fromEngine map[string]string
}

func (m *formalSyncIDs) engineID(symbolic string) string {
	id, known := m.candidateID(symbolic)
	if !known {
		m.bind(symbolic, id)
	}
	return id
}

// candidateID returns the KSUID bound to symbolic, or a fresh unbound one.
// start_new binds a fresh id only after the engine accepts it, so a
// refused start_new leaves no mapping behind.
func (m *formalSyncIDs) candidateID(symbolic string) (string, bool) {
	if id, ok := m.toEngine[symbolic]; ok {
		return id, true
	}
	return ksuid.New().String(), false
}

func (m *formalSyncIDs) bind(symbolic, id string) {
	m.toEngine[symbolic] = id
	m.fromEngine[id] = symbolic
}

func runFormalSyncCase(t *testing.T, c formalSyncCase) {
	ctx := context.Background()
	e := newFormalEngine(t)
	if len(c.Ops) == 0 {
		t.Fatal("sync case with no ops")
	}
	ids := &formalSyncIDs{toEngine: map[string]string{}, fromEngine: map[string]string{}}
	for i, op := range c.Ops {
		if op.Result == nil {
			t.Fatalf("op %d (%s): required field \"result\" is absent", i, op.Op)
		}
		got, ok := formalSyncStep(ctx, t, e, ids, i, op.Op, op.ID, op.Type, *op.Result)
		if !ok {
			t.Fatalf("op %d: unknown sync op %q", i, op.Op)
		}
		if got != *op.Result {
			t.Fatalf("op %d (%s): got %q, want %q", i, op.Op, got, *op.Result)
		}
	}
}

// formalSyncStep applies one start_new, write, end, resume, or
// latest_finished op of the sync and reopen families and returns the
// observed result string. ok is false for any other op name.
func formalSyncStep(ctx context.Context, t *testing.T, e *Engine, ids *formalSyncIDs, i int, name string, idField, typeField *string, want string) (string, bool) {
	t.Helper()
	requireID := func() string {
		if idField == nil {
			t.Fatalf("op %d (%s): required field \"id\" is absent", i, name)
		}
		return requireProtoString(t, "id", *idField)
	}
	requireType := func() string {
		if typeField == nil {
			t.Fatalf("op %d (%s): required field \"type\" is absent", i, name)
		}
		return *typeField
	}
	requireNoIDOrType := func() {
		if idField != nil || typeField != nil {
			t.Fatalf("op %d (%s): \"id\" and \"type\" must be absent", i, name)
		}
	}
	requireWant := func(allowed ...string) {
		for _, a := range allowed {
			if want == a {
				return
			}
		}
		t.Fatalf("op %d: unknown %s result %q", i, name, want)
	}
	switch name {
	case "start_new":
		id := requireID()
		st := formalSyncType(t, requireType(), false)
		requireWant("ok", "sync_in_progress")
		// ResetForNewSync returns an unwrapped error while a sync
		// started by StartNewSync* is open; the flag is read before
		// the call.
		fresh := e.IsFreshSync()
		engineID, known := ids.candidateID(id)
		gotID, err := e.StartNewSyncWithID(ctx, st, engineID, "")
		switch {
		case err == nil:
			if gotID != engineID {
				t.Fatalf("op %d: StartNewSyncWithID returned %q, want %q", i, gotID, engineID)
			}
			if !known {
				ids.bind(id, engineID)
			}
			return "ok", true
		case fresh:
			return "sync_in_progress", true
		default:
			t.Fatalf("op %d: StartNewSyncWithID(%q as %s): %v", i, id, engineID, err)
		}
	case "write":
		requireNoIDOrType()
		requireWant("allowed", "no_current_sync", "engine_sealed")
		err := e.PutResources(ctx, formalResource(t, "user", "u1", "w"))
		switch {
		case err == nil:
			return "allowed", true
		case errors.Is(err, ErrEngineSealed):
			return "engine_sealed", true
		case errors.Is(err, ErrNoCurrentSync):
			return "no_current_sync", true
		default:
			t.Fatalf("op %d: PutResources: unexpected error: %v", i, err)
		}
	case "end":
		requireNoIDOrType()
		requireWant("ok", "no_current_sync")
		// endSync returns an unwrapped error, not ErrNoCurrentSync,
		// when no sync is bound; the binding is read before the call.
		unbound := e.CurrentSyncID() == ""
		err := e.EndSync(ctx)
		switch {
		case err == nil:
			return "ok", true
		case unbound || errors.Is(err, ErrNoCurrentSync):
			return "no_current_sync", true
		default:
			t.Fatalf("op %d: EndSync: unexpected error: %v", i, err)
		}
	case "resume":
		id := requireID()
		if typeField != nil {
			t.Fatalf("op %d (resume): \"type\" must be absent", i)
		}
		requireWant("ok", "not_found")
		_, err := e.ResumeSync(ctx, connectorstore.SyncTypeAny, ids.engineID(id))
		switch {
		case err == nil:
			return "ok", true
		case errors.Is(err, pebble.ErrNotFound):
			return "not_found", true
		default:
			t.Fatalf("op %d: ResumeSync(%q): unexpected error: %v", i, id, err)
		}
	case "latest_finished":
		if idField != nil {
			t.Fatalf("op %d (latest_finished): \"id\" must be absent", i)
		}
		st := formalSyncType(t, requireType(), true)
		id, err := e.LatestFinishedSyncID(ctx, st)
		if err != nil {
			t.Fatalf("op %d: LatestFinishedSyncID: %v", i, err)
		}
		symbolic, known := ids.fromEngine[id]
		switch {
		case id == "":
			return "none", true
		case known:
			return symbolic, true
		default:
			t.Fatalf("op %d: LatestFinishedSyncID returned %q, which no start_new or resume op named", i, id)
		}
	}
	return "", false
}

// formalGrantParts is a decoded formalGrant: the five identity components
// and the stored external_id.
type formalGrantParts struct {
	rt, rid, ext, prt, prid, extID string
}

func (p formalGrantParts) String() string {
	return fmt.Sprintf("(%x,%x,%x)/%x/%x#%x", p.rt, p.rid, p.ext, p.prt, p.prid, p.extID)
}

func (p formalGrantParts) identity() grantIdentity {
	return grantIdentity{
		entitlement:     entitlementIdentityFromParts(p.rt, p.rid, p.ext),
		principalTypeID: p.prt,
		principalID:     p.prid,
	}
}

// publicID is the id V3GrantToV2 rebuilds when the stored external_id is
// empty.
func (p formalGrantParts) publicID() string { return p.ext + ":" + p.prt + ":" + p.prid }

func requireFormalEntRef(t *testing.T, field string, ref *formalEntRef) (string, string, string) {
	t.Helper()
	if ref == nil {
		t.Fatalf("required object %q is absent", field)
	}
	return requireProtoString(t, field+".rt", requireHex(t, field+".rt", ref.RT)),
		requireProtoString(t, field+".rid", requireHex(t, field+".rid", ref.RID)),
		requireProtoString(t, field+".ext", requireHex(t, field+".ext", ref.Ext))
}

func requireFormalGrant(t *testing.T, field string, g formalGrant) formalGrantParts {
	t.Helper()
	rt, rid, ext := requireFormalEntRef(t, field+".ent", g.Ent)
	return formalGrantParts{
		rt: rt, rid: rid, ext: ext,
		prt:   requireProtoString(t, field+".prt", requireHex(t, field+".prt", g.PRT)),
		prid:  requireProtoString(t, field+".prid", requireHex(t, field+".prid", g.PRID)),
		extID: requireProtoString(t, field+".ext_id", requireHex(t, field+".ext_id", g.ExtID)),
	}
}

func requireFormalGrants(t *testing.T, field string, gs []formalGrant) []formalGrantParts {
	t.Helper()
	out := make([]formalGrantParts, 0, len(gs))
	for i, g := range gs {
		out = append(out, requireFormalGrant(t, fmt.Sprintf("%s[%d]", field, i), g))
	}
	return out
}

func formalV2Entitlement(rt, rid, ext string) *v2.Entitlement {
	return v2.Entitlement_builder{
		Id: ext,
		Resource: v2.Resource_builder{
			Id: v2.ResourceId_builder{ResourceType: rt, Resource: rid}.Build(),
		}.Build(),
	}.Build()
}

func formalV2Grant(p formalGrantParts) *v2.Grant {
	return v2.Grant_builder{
		Id:          p.extID,
		Entitlement: formalV2Entitlement(p.rt, p.rid, p.ext),
		Principal: v2.Resource_builder{
			Id: v2.ResourceId_builder{ResourceType: p.prt, Resource: p.prid}.Build(),
		}.Build(),
	}.Build()
}

func formalV2Grants(ps []formalGrantParts) []*v2.Grant {
	out := make([]*v2.Grant, 0, len(ps))
	for _, p := range ps {
		out = append(out, formalV2Grant(p))
	}
	return out
}

// formalGotGrant reads a returned v2 grant's identity through its refs and
// its stored external_id from the v3 record at that identity, since v2
// Grant.Id is the rebuilt public id when the stored one is empty. It also
// checks the v2 Grant.Id rule from ORACLE_SCHEMA.md.
func formalGotGrant(t *testing.T, e *Engine, g *v2.Grant) formalGrantParts {
	t.Helper()
	ent := g.GetEntitlement()
	p := formalGrantParts{
		rt:   ent.GetResource().GetId().GetResourceType(),
		rid:  ent.GetResource().GetId().GetResource(),
		ext:  ent.GetId(),
		prt:  g.GetPrincipal().GetId().GetResourceType(),
		prid: g.GetPrincipal().GetId().GetResource(),
	}
	rec, err := e.getGrantRecordByIdentity(p.identity())
	if err != nil {
		t.Fatalf("getGrantRecordByIdentity(%v) for a returned grant: %v", p, err)
	}
	p.extID = rec.GetExternalId()
	wantID := p.extID
	if wantID == "" {
		wantID = p.publicID()
	}
	if g.GetId() != wantID {
		t.Fatalf("returned grant %v has v2 Id %x, want %x", p, g.GetId(), wantID)
	}
	return p
}

func formalGotGrants(t *testing.T, e *Engine, gs []*v2.Grant) []formalGrantParts {
	t.Helper()
	out := make([]formalGrantParts, 0, len(gs))
	for _, g := range gs {
		out = append(out, formalGotGrant(t, e, g))
	}
	return out
}

func requireFormalGrantList(t *testing.T, what string, got, want []formalGrantParts) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("%s: got %d grants %v, want %d %v", what, len(got), got, len(want), want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("%s[%d] = %v, want %v\n got  %v\n want %v", what, i, got[i], want[i], got, want)
		}
	}
}

func formalPutGrants(ctx context.Context, t *testing.T, e *Engine, what string, ps []formalGrantParts) {
	t.Helper()
	if len(ps) == 0 {
		return
	}
	if err := e.PutGrants(ctx, formalV2Grants(ps)...); err != nil {
		t.Fatalf("%s: PutGrants(%v): %v", what, ps, err)
	}
}

// formalGrantOpIdentity decodes the identity of a delete or read op.
func formalGrantOpIdentity(t *testing.T, i int, op formalGrantOp) formalGrantParts {
	t.Helper()
	field := fmt.Sprintf("ops[%d]", i)
	rt, rid, ext := requireFormalEntRef(t, field+".ent", op.Ent)
	return formalGrantParts{
		rt: rt, rid: rid, ext: ext,
		prt:  requireProtoString(t, field+".prt", requireHex(t, field+".prt", op.PRT)),
		prid: requireProtoString(t, field+".prid", requireHex(t, field+".prid", op.PRID)),
	}
}

func formalDeleteGrant(ctx context.Context, t *testing.T, e *Engine, i int, p formalGrantParts) {
	t.Helper()
	rec := V2GrantToV3(e.CurrentSyncID(), formalV2Grant(p))
	if err := e.DeleteGrantByIdentityRefs(ctx, rec); err != nil {
		t.Fatalf("op %d: DeleteGrantByIdentityRefs(%v): %v", i, p, err)
	}
}

func listAllFormalGrants(ctx context.Context, t *testing.T, e *Engine) []formalGrantParts {
	t.Helper()
	var out []formalGrantParts
	token := ""
	for {
		resp, err := e.ListGrants(ctx, v2.GrantsServiceListGrantsRequest_builder{
			PageSize:  MaxPageSize,
			PageToken: token,
		}.Build())
		if err != nil {
			t.Fatalf("ListGrants: %v", err)
		}
		out = append(out, formalGotGrants(t, e, resp.GetList())...)
		token = resp.GetNextPageToken()
		if token == "" {
			return out
		}
	}
}

func runFormalGrantWritesCase(t *testing.T, c formalGrantWritesCase) {
	if c.Final == nil {
		t.Fatal("required field \"final\" is absent")
	}
	want := requireFormalGrants(t, "final", *c.Final)
	ctx, e := newFormalEngineWithSync(t)
	for i, op := range c.Ops {
		if op.Grants != nil {
			t.Fatalf("op %d (%s): \"grants\" must be absent", i, op.Op)
		}
		switch op.Op {
		case "put":
			if op.Batch == nil || op.Ent != nil || op.PRT.present || op.PRID.present {
				t.Fatalf("op %d: put requires \"batch\" and nothing else", i)
			}
			formalPutGrants(ctx, t, e, fmt.Sprintf("op %d", i), requireFormalGrants(t, fmt.Sprintf("ops[%d].batch", i), *op.Batch))
		case "delete":
			if op.Batch != nil {
				t.Fatalf("op %d: delete with \"batch\"", i)
			}
			formalDeleteGrant(ctx, t, e, i, formalGrantOpIdentity(t, i, op))
		default:
			t.Fatalf("op %d: unknown grant_writes op %q", i, op.Op)
		}
	}
	requireFormalGrantList(t, "final", listAllFormalGrants(ctx, t, e), want)
}

func listAllFormalEntitlements(ctx context.Context, t *testing.T, e *Engine) []*v2.Entitlement {
	t.Helper()
	var out []*v2.Entitlement
	token := ""
	for {
		resp, err := e.ListEntitlements(ctx, v2.EntitlementsServiceListEntitlementsRequest_builder{
			PageSize:  MaxPageSize,
			PageToken: token,
		}.Build())
		if err != nil {
			t.Fatalf("ListEntitlements: %v", err)
		}
		out = append(out, resp.GetList()...)
		token = resp.GetNextPageToken()
		if token == "" {
			return out
		}
	}
}

func formalEntitlementSummary(es []*v2.Entitlement) []string {
	out := make([]string, 0, len(es))
	for _, en := range es {
		id := en.GetResource().GetId()
		out = append(out, fmt.Sprintf("(%x,%x,%x)=%s", id.GetResourceType(), id.GetResource(), en.GetId(), en.GetDisplayName()))
	}
	return out
}

func runFormalEntWritesCase(t *testing.T, c formalEntWritesCase) {
	if c.Final == nil {
		t.Fatal("required field \"final\" is absent")
	}
	ctx, e := newFormalEngineWithSync(t)
	for i, op := range c.Ops {
		switch op.Op {
		case "put":
			if op.Batch == nil || op.RT.present || op.RID.present || op.Ext.present {
				t.Fatalf("op %d: put requires \"batch\" and nothing else", i)
			}
			batch := make([]*v2.Entitlement, 0, len(*op.Batch))
			for j, r := range *op.Batch {
				field := fmt.Sprintf("ops[%d].batch[%d]", i, j)
				if r.Value == nil {
					t.Fatalf("%s without \"value\"", field)
				}
				en := formalV2Entitlement(
					requireProtoString(t, field+".rt", requireHex(t, field+".rt", r.RT)),
					requireProtoString(t, field+".rid", requireHex(t, field+".rid", r.RID)),
					requireProtoString(t, field+".ext", requireHex(t, field+".ext", r.Ext)))
				en.SetDisplayName(requireProtoString(t, field+".value", *r.Value))
				batch = append(batch, en)
			}
			if len(batch) > 0 {
				if err := e.PutEntitlements(ctx, batch...); err != nil {
					t.Fatalf("op %d: PutEntitlements: %v", i, err)
				}
			}
		case "delete":
			if op.Batch != nil {
				t.Fatalf("op %d: delete with \"batch\"", i)
			}
			field := fmt.Sprintf("ops[%d]", i)
			rt := requireProtoString(t, field+".rt", requireHex(t, field+".rt", op.RT))
			rid := requireProtoString(t, field+".rid", requireHex(t, field+".rid", op.RID))
			ext := requireProtoString(t, field+".ext", requireHex(t, field+".ext", op.Ext))
			if err := e.DeleteEntitlementRecordByIdentity(ctx, rt, rid, ext); err != nil {
				t.Fatalf("op %d: DeleteEntitlementRecordByIdentity: %v", i, err)
			}
		default:
			t.Fatalf("op %d: unknown entitlement_writes op %q", i, op.Op)
		}
	}
	got := listAllFormalEntitlements(ctx, t, e)
	want := *c.Final
	if len(got) != len(want) {
		t.Fatalf("listed %d entitlements, want %d: got %v", len(got), len(want), formalEntitlementSummary(got))
	}
	for i, w := range want {
		field := fmt.Sprintf("final[%d]", i)
		if w.Value == nil {
			t.Fatalf("%s without \"value\"", field)
		}
		wantRT, wantRID, wantExt := requireHex(t, field+".rt", w.RT), requireHex(t, field+".rid", w.RID), requireHex(t, field+".ext", w.Ext)
		g := got[i]
		id := g.GetResource().GetId()
		if id.GetResourceType() != wantRT || id.GetResource() != wantRID || g.GetId() != wantExt || g.GetDisplayName() != *w.Value {
			t.Fatalf("%s = (%x,%x,%x)=%s, want (%x,%x,%x)=%s; full list %v", field,
				id.GetResourceType(), id.GetResource(), g.GetId(), g.GetDisplayName(), wantRT, wantRID, wantExt, *w.Value,
				formalEntitlementSummary(got))
		}
	}
}

func runFormalGrantListCase(t *testing.T, c formalGrantListCase) {
	if c.Grants == nil || c.Query == nil || c.PageSize == nil || c.Pages == nil {
		t.Fatal("grant_list case requires \"grants\", \"query\", \"page_size\", and \"pages\"")
	}
	grants := requireFormalGrants(t, "grants", *c.Grants)
	rt, rid, ext := requireFormalEntRef(t, "query.ent", c.Query.Ent)
	req := reader_v2.GrantsReaderServiceListGrantsForEntitlementRequest_builder{
		Entitlement: formalV2Entitlement(rt, rid, ext),
		PageSize:    *c.PageSize,
	}.Build()
	pointLookup := false
	switch {
	case c.Query.PRID.present:
		prt := requireProtoString(t, "query.prt", requireHex(t, "query.prt", c.Query.PRT))
		prid := requireProtoString(t, "query.prid", c.Query.PRID.b)
		req.SetPrincipalId(v2.ResourceId_builder{ResourceType: prt, Resource: prid}.Build())
		pointLookup = true
	case c.Query.PRT.present:
		req.SetPrincipalResourceTypeIds([]string{requireProtoString(t, "query.prt", c.Query.PRT.b)})
	}
	if pointLookup && len(*c.Pages) != 1 {
		t.Fatalf("point lookup case with %d pages, want 1", len(*c.Pages))
	}
	ctx, e := newFormalEngineWithSync(t)
	formalPutGrants(ctx, t, e, "grants", grants)
	token := ""
	for i, page := range *c.Pages {
		if page.Grants == nil || page.HasNext == nil {
			t.Fatalf("pages[%d] requires \"grants\" and \"has_next\"", i)
		}
		want := requireFormalGrants(t, fmt.Sprintf("pages[%d].grants", i), *page.Grants)
		req.SetPageToken(token)
		resp, err := e.ListGrantsForEntitlement(ctx, req)
		if err != nil {
			t.Fatalf("pages[%d]: ListGrantsForEntitlement: %v", i, err)
		}
		requireFormalGrantList(t, fmt.Sprintf("pages[%d]", i), formalGotGrants(t, e, resp.GetList()), want)
		token = resp.GetNextPageToken()
		if gotNext := token != ""; gotNext != *page.HasNext {
			t.Fatalf("pages[%d] has_next = %v, want %v", i, gotNext, *page.HasNext)
		}
		if token == "" && i != len(*c.Pages)-1 {
			t.Fatalf("token ended after page %d, want %d pages", i, len(*c.Pages))
		}
	}
	if token != "" {
		t.Fatalf("token still set after the last expected page %d", len(*c.Pages)-1)
	}
}

// formalByPrincipalPageSize is small so a read crosses page boundaries.
const formalByPrincipalPageSize = 2

func listAllFormalGrantsForPrincipal(ctx context.Context, t *testing.T, e *Engine, prt, prid string) []formalGrantParts {
	t.Helper()
	var out []formalGrantParts
	token := ""
	for {
		resp, err := e.ListGrantsForPrincipal(ctx, reader_v2.GrantsReaderServiceListGrantsForPrincipalRequest_builder{
			PrincipalId: v2.ResourceId_builder{ResourceType: prt, Resource: prid}.Build(),
			PageSize:    formalByPrincipalPageSize,
			PageToken:   token,
		}.Build())
		if err != nil {
			t.Fatalf("ListGrantsForPrincipal(%x, %x): %v", prt, prid, err)
		}
		out = append(out, formalGotGrants(t, e, resp.GetList())...)
		token = resp.GetNextPageToken()
		if token == "" {
			return out
		}
	}
}

func runFormalGrantsByPrincipalCase(t *testing.T, c formalGrantsByPrincipalCase) {
	if len(c.Ops) == 0 {
		t.Fatal("grants_by_principal case with no ops")
	}
	ctx, e := newFormalEngineWithSync(t)
	ended := false
	for i, op := range c.Ops {
		if ended && op.Op != "read" {
			t.Fatalf("op %d (%s) after end_sync; only a read may follow it", i, op.Op)
		}
		switch op.Op {
		case "put", "put_deferred":
			if op.Batch == nil || op.Ent != nil || op.PRT.present || op.PRID.present || op.Grants != nil {
				t.Fatalf("op %d: %s requires \"batch\" and nothing else", i, op.Op)
			}
			batch := requireFormalGrants(t, fmt.Sprintf("ops[%d].batch", i), *op.Batch)
			if op.Op == "put" {
				formalPutGrants(ctx, t, e, fmt.Sprintf("op %d", i), batch)
				continue
			}
			records := make([]*v3.GrantRecord, 0, len(batch))
			for _, p := range batch {
				records = append(records, V2GrantToV3(e.CurrentSyncID(), formalV2Grant(p)))
			}
			if err := e.PutExpandedGrantRecords(ctx, records); err != nil {
				t.Fatalf("op %d: PutExpandedGrantRecords(%v): %v", i, batch, err)
			}
		case "delete":
			if op.Batch != nil || op.Grants != nil {
				t.Fatalf("op %d: delete with \"batch\" or \"grants\"", i)
			}
			formalDeleteGrant(ctx, t, e, i, formalGrantOpIdentity(t, i, op))
		case "end_sync":
			if op.Batch != nil || op.Ent != nil || op.PRT.present || op.PRID.present || op.Grants != nil {
				t.Fatalf("op %d: end_sync takes no fields", i)
			}
			if err := e.EndSync(ctx); err != nil {
				t.Fatalf("op %d: EndSync: %v", i, err)
			}
			ended = true
		case "read":
			if op.Batch != nil || op.Ent != nil || op.Grants == nil {
				t.Fatalf("op %d: read requires \"prt\", \"prid\", and \"grants\" only", i)
			}
			field := fmt.Sprintf("ops[%d]", i)
			prt := requireProtoString(t, field+".prt", requireHex(t, field+".prt", op.PRT))
			prid := requireProtoString(t, field+".prid", requireHex(t, field+".prid", op.PRID))
			want := requireFormalGrants(t, field+".grants", *op.Grants)
			requireFormalGrantList(t, fmt.Sprintf("op %d read", i), listAllFormalGrantsForPrincipal(ctx, t, e, prt, prid), want)
		default:
			t.Fatalf("op %d: unknown grants_by_principal op %q", i, op.Op)
		}
	}
}

func runFormalGrantBareIDCase(t *testing.T, c formalGrantBareIDCase) {
	lookup := requireProtoString(t, "lookup", requireHex(t, "lookup", c.Lookup))
	switch c.Expected {
	case "not_found", "ambiguous":
		if c.Found != nil {
			t.Fatalf("expected %q with a \"found\" object", c.Expected)
		}
	case "found":
		if c.Found == nil {
			t.Fatal("expected \"found\" without a \"found\" object")
		}
	default:
		t.Fatalf("unknown grant_bare_id expected %q", c.Expected)
	}
	ctx, e := newFormalEngineWithSync(t)
	ents := make([]*v2.Entitlement, 0, len(c.Entitlements))
	for i := range c.Entitlements {
		ents = append(ents, formalV2Entitlement(requireFormalEntRef(t, fmt.Sprintf("entitlements[%d]", i), &c.Entitlements[i])))
	}
	if len(ents) > 0 {
		if err := e.PutEntitlements(ctx, ents...); err != nil {
			t.Fatalf("PutEntitlements: %v", err)
		}
	}
	formalPutGrants(ctx, t, e, "grants", requireFormalGrants(t, "grants", c.Grants))
	resp, err := e.GetGrant(ctx, reader_v2.GrantsReaderServiceGetGrantRequest_builder{GrantId: lookup}.Build())
	var got string
	switch {
	case err == nil:
		got = "found"
	case errors.Is(err, pebble.ErrNotFound):
		got = "not_found"
	case errors.Is(err, ErrAmbiguousExternalID):
		got = "ambiguous"
	default:
		t.Fatalf("GetGrant(%x): unexpected error: %v", lookup, err)
	}
	if got != c.Expected {
		detail := ""
		if got == "found" {
			detail = formalGotGrant(t, e, resp.GetGrant()).String()
		}
		t.Fatalf("GetGrant(%x) = %s %s (err=%v), want %s", lookup, got, detail, err, c.Expected)
	}
	if got != "found" {
		return
	}
	want := requireFormalGrant(t, "found", *c.Found)
	if g := formalGotGrant(t, e, resp.GetGrant()); g != want {
		t.Fatalf("GetGrant(%x) = %v, want %v", lookup, g, want)
	}
}

// MarshalJSON lets a failed property case log its decoded response.
// An absent field marshals as null.
func (h hexField) MarshalJSON() ([]byte, error) {
	if !h.present {
		return []byte("null"), nil
	}
	return json.Marshal(hex.EncodeToString([]byte(h.b)))
}

