func hexPtr(s string) *string {
	h := hex.EncodeToString([]byte(s))
	return &h
}

func hexStr(s string) string { return hex.EncodeToString([]byte(s)) }

func strPtr(s string) *string { return &s }

type formalGen struct{ r *rand.Rand }

// rawByte is biased toward the bytes the key encoders treat specially.
func (g formalGen) rawByte() byte {
	switch n := g.r.IntN(12); {
	case n < 2:
		return 0x00
	case n < 4:
		return 0x01
	case n < 6:
		return ':'
	case n < 10:
		return "abxyz"[g.r.IntN(5)]
	default:
		return formalHighBytes[g.r.IntN(len(formalHighBytes))]
	}
}

var formalHighBytes = func() []byte {
	var out []byte
	for b := byte(0x80); ; b++ {
		out = append(out, b)
		if b == 0xff {
			return out
		}
	}
}()

// rawBytes returns arbitrary bytes, not necessarily valid UTF-8.
func (g formalGen) rawBytes(minLen, maxLen int) string {
	b := make([]byte, minLen+g.r.IntN(maxLen-minLen+1))
	for i := range b {
		b[i] = g.rawByte()
	}
	return string(b)
}

var formalUTF8Fragments = []string{
	"a", "b", "z", "0", "9", "_", "-", ":", "user", "group", "é", "日本", "ß",
}

// utf8String concatenates whole fragments, so the result is valid UTF-8.
func (g formalGen) utf8String(minFrags, maxFrags int) string {
	frags := make([]string, minFrags+g.r.IntN(maxFrags-minFrags+1))
	for i := range frags {
		frags[i] = formalUTF8Fragments[g.r.IntN(len(formalUTF8Fragments))]
	}
	return strings.Join(frags, "")
}

// entitlementExt sometimes returns rt:rid:tail so the stripped branch of
// entitlementIdentityFromParts is reached.
func (g formalGen) entitlementExt(rt, rid string, stripProb int, part func() string) string {
	if g.r.IntN(stripProb) == 0 {
		return rt + ":" + rid + ":" + part()
	}
	return part()
}

func (g formalGen) keyCase(i int) formalKeyRequest {
	c := formalKeyRequest{Name: fmt.Sprintf("property/keys/%d", i)}
	part := func() string { return g.rawBytes(0, 6) }
	nonEmpty := func() string { return g.rawBytes(1, 6) }
	switch g.r.IntN(4) {
	case 0:
		c.Kind = "resource_type"
		c.Ext = hexPtr(part())
	case 1:
		c.Kind = "resource"
		c.RT, c.RID = hexPtr(part()), hexPtr(part())
	case 2:
		c.Kind = "entitlement"
		rt, rid := nonEmpty(), nonEmpty()
		c.RT, c.RID, c.Ext = hexPtr(rt), hexPtr(rid), hexPtr(g.entitlementExt(rt, rid, 3, part))
	default:
		c.Kind = "grant"
		rt, rid := nonEmpty(), nonEmpty()
		c.RT, c.RID, c.Ext = hexPtr(rt), hexPtr(rid), hexPtr(g.entitlementExt(rt, rid, 3, nonEmpty))
		c.PRT, c.PRID = hexPtr(nonEmpty()), hexPtr(nonEmpty())
	}
	return c
}

func (g formalGen) stripCase() formalStripRequest {
	rt, rid := g.rawBytes(1, 6), g.rawBytes(1, 6)
	ext := g.entitlementExt(rt, rid, 2, func() string { return g.rawBytes(0, 6) })
	return formalStripRequest{RT: hexStr(rt), RID: hexStr(rid), Ext: hexStr(ext)}
}

func (g formalGen) writesCase(i int) formalWritesRequest {
	pool := make([]string, 1+g.r.IntN(5))
	for j := range pool {
		pool[j] = g.utf8String(1, 3)
	}
	c := formalWritesRequest{Name: fmt.Sprintf("property/writes/%d", i), RT: hexStr(g.utf8String(1, 3))}
	value := 0
	for range 1 + g.r.IntN(6) {
		if g.r.IntN(3) == 0 {
			rid := pool[g.r.IntN(len(pool))]
			if g.r.IntN(4) == 0 {
				rid = "absent" + g.utf8String(0, 2)
			}
			c.Ops = append(c.Ops, formalWriteOpRequest{Op: "delete", RID: hexPtr(rid)})
			continue
		}
		batch := make([]formalRecordRequest, 1+g.r.IntN(4))
		for j := range batch {
			value++
			batch[j] = formalRecordRequest{RID: hexStr(pool[g.r.IntN(len(pool))]), Value: fmt.Sprintf("v%d", value)}
		}
		c.Ops = append(c.Ops, formalWriteOpRequest{Op: "put", Batch: batch})
	}
	return c
}

func (g formalGen) paginationCase(i int) formalPaginationRequest {
	n := g.r.Uint32N(13)
	seen := map[string]bool{}
	rids := []string{}
	for added := uint32(0); added < n; {
		rid := g.utf8String(1, 4)
		if seen[rid] {
			continue
		}
		seen[rid] = true
		rids = append(rids, hexStr(rid))
		added++
	}
	g.r.Shuffle(len(rids), func(a, b int) { rids[a], rids[b] = rids[b], rids[a] })
	sizes := []uint32{0, 1, 2, 3, 5, 7, n, n + 1, 13}
	return formalPaginationRequest{
		Name:     fmt.Sprintf("property/pagination/%d", i),
		RT:       hexStr(g.utf8String(1, 3)),
		RIDs:     rids,
		PageSize: sizes[g.r.IntN(len(sizes))],
	}
}

func (g formalGen) bareIDCase(i int) formalBareIDRequest {
	type owner struct{ rt, rid string }
	owners := make([]owner, 1+g.r.IntN(3))
	for j := range owners {
		owners[j] = owner{rt: g.utf8String(1, 2), rid: g.utf8String(1, 2)}
	}
	extPool := []string{"member", "admin", "é", "日本"}
	type ent struct{ rt, rid, ext string }
	seen := map[ent]bool{}
	c := formalBareIDRequest{Name: fmt.Sprintf("property/bare_id/%d", i)}
	var exts []string
	for want := 1 + g.r.IntN(5); len(c.Entitlements) < want; {
		o := owners[g.r.IntN(len(owners))]
		e := ent{o.rt, o.rid, g.entitlementExt(o.rt, o.rid, 4, func() string { return extPool[g.r.IntN(len(extPool))] })}
		if seen[e] {
			continue
		}
		seen[e] = true
		exts = append(exts, e.ext)
		c.Entitlements = append(c.Entitlements, formalEntRefRequest{RT: hexStr(e.rt), RID: hexStr(e.rid), Ext: hexStr(e.ext)})
	}
	lookup := "fresh" + g.utf8String(0, 2)
	if g.r.IntN(4) != 0 {
		lookup = exts[g.r.IntN(len(exts))]
	}
	c.Lookup = hexStr(lookup)
	return c
}

func (g formalGen) syncCase(i int) formalSyncRequest {
	ids := []string{"s1", "s2", "s3"}
	startTypes := []string{"full", "partial", "resources_only"}
	latestTypes := []string{"any", "full", "partial", "resources_only"}
	c := formalSyncRequest{Name: fmt.Sprintf("property/sync/%d", i)}
	for range 1 + g.r.IntN(7) {
		var op formalSyncOpRequest
		switch g.r.IntN(5) {
		case 0:
			op = formalSyncOpRequest{Op: "start_new", ID: strPtr(ids[g.r.IntN(len(ids))]), Type: strPtr(startTypes[g.r.IntN(len(startTypes))])}
		case 1:
			op = formalSyncOpRequest{Op: "write"}
		case 2:
			op = formalSyncOpRequest{Op: "end"}
		case 3:
			id := ids[g.r.IntN(len(ids))]
			if g.r.IntN(5) == 0 {
				id = "s9"
			}
			op = formalSyncOpRequest{Op: "resume", ID: strPtr(id)}
		default:
			op = formalSyncOpRequest{Op: "latest_finished", Type: strPtr(latestTypes[g.r.IntN(len(latestTypes))])}
		}
		c.Ops = append(c.Ops, op)
	}
	return c
}

